import math
from itertools import combinations

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def gcd_three(a, b, c):
    return gcd(a, gcd(b, c))

def is_good_set(U):
    if len(U) != 3:
        return False

    elements = sorted(list(U))
    a, b, c = elements

    # Condition 1: GCD of the three distinct elements is 1.
    if gcd_three(a, b, c) != 1:
        return False

    # Condition 2: Divisibility requirements
    # (a, b) -> c | ab
    if (a * b) % c != 0:
        return False

    # (a, c) -> b | ac
    if (a * c) % b != 0:
        return False

    # (b, c) -> a | bc
    if (b * c) % a != 0:
        return False

    return True

good_numbers = set()
limit = 40 # Increased limit for the largest element in U

print("Searching for good sets U with |U|=3 where max(U) <= {}".format(limit))

found_sets = []
for a in range(2, limit + 1):
    for b in range(a + 1, limit + 1):
        for c in range(b + 1, limit + 1):
            U = {a, b, c}
            if is_good_set(U):
                m = a * b * c
                good_numbers.add(m)
                found_sets.append((m, a, b, c))

# Sort the good numbers
sorted_good_numbers = sorted(list(good_numbers))

print("\n--- Found Good Sets and Products (U={a, b, c}, m=abc) ---")
# Only print the first 25 for brevity
for m, a, b, c in found_sets[:25]:
    print(f"U={a, b, c}, m={m}")

print("\n--- List of Good Numbers Found ---")
print(sorted_good_numbers)

# We need at least 20 good numbers.
if len(sorted_good_numbers) >= 20:
    print(f"\nThe 20th smallest good number is: {sorted_good_numbers[19]}")
else:
    print(f"\nWarning: Only found {len(sorted_good_numbers)} good numbers up to max element {limit}. Need to increase limit further.")

